import "server-only";
import { mkdir, readFile, writeFile } from "node:fs/promises";
import { dirname, resolve, sep } from "node:path";

/**
 * Where uploaded images live. Locally that's .data/uploads on this machine;
 * R2 replaces it by implementing the same three methods (SPEC.md: Cloudflare R2).
 */
export interface ImageStore {
  put(key: string, bytes: Uint8Array): Promise<void>;
  get(key: string): Promise<Uint8Array | null>;
  /** The URL the app renders; served through an auth-checked route, never publicly. */
  url(key: string): string;
}

// Keys are generated by the server: projects/<slug>/<uuid>.<ext>. Anything else is refused.
const KEY_PATTERN = /^projects\/[a-z0-9-]+\/[a-f0-9-]{36}\.(png|jpg|webp)$/;

export function isValidKey(key: string): boolean {
  return KEY_PATTERN.test(key);
}

class LocalImageStore implements ImageStore {
  // UPLOADS_DIR lets tests write somewhere disposable.
  private readonly root = resolve(process.env.UPLOADS_DIR ?? ".data/uploads");

  private pathFor(key: string): string {
    if (!isValidKey(key)) throw new Error("invalid storage key");
    const path = resolve(this.root, key);
    // Belt and braces against path traversal, on top of the key pattern.
    if (!path.startsWith(this.root + sep)) throw new Error("invalid storage key");
    return path;
  }

  async put(key: string, bytes: Uint8Array): Promise<void> {
    const path = this.pathFor(key);
    await mkdir(dirname(path), { recursive: true });
    await writeFile(path, bytes, { flag: "wx" });
  }

  async get(key: string): Promise<Uint8Array | null> {
    try {
      return await readFile(this.pathFor(key));
    } catch {
      return null;
    }
  }

  url(key: string): string {
    return `/api/files/${key}`;
  }
}

let store: ImageStore | undefined;

export function getImageStore(): ImageStore {
  store ??= new LocalImageStore();
  return store;
}
